#!/usr/bin/env python3
"""Round 214r tiles (16 October 2026): the first copy of the Reproduction
capture map's places and boxes, so its row on the Culprits map draws before the
next full refresh rebuilds them from the maps repo. Writes two new files in
sitemaps/ (each only if it differs) and touches nothing else, so it can go in
before or after any other round.

Upload to WelcomeToYourGalaxy/culprits-tiles-more, folder patches/.
"""
import base64, pathlib, sys
here = pathlib.Path(__file__).resolve().parent
ROOT = here.parent if here.name == "patches" else (here.parent.parent if here.name == "failed" else pathlib.Path.cwd())
FILES = {'sitemaps/reproduction_capture.places.geojson': '', 'sitemaps/reproduction_capture.boxes.json': ''}
wrote = 0
for rel, b64 in FILES.items():
    p = ROOT / rel
    data = base64.b64decode(b64)
    if p.exists() and p.read_bytes() == data:
        continue
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(data)
    wrote += 1
print(f"round214r tiles: {wrote} file(s) written, {len(FILES) - wrote} already current.")
